// Vollstaendige, rein lesende Strukturinventur der zwoelf im
// edoobox-Schaubild genannten Ressourcen. Es werden niemals Feldwerte,
// Namen, E-Mail-Adressen oder andere Personenangaben ausgegeben.

const auth = $input.first().json;
const token = typeof auth.data === 'string' ? auth.data : auth.access_token;
const edid = auth.edid ?? auth?.data?.edid;

if (!token || !edid) {
  throw new Error('Token oder edid nicht gefunden. Vorhandene Felder: ' + Object.keys(auth).join(', '));
}

const headers = {
  edid,
  'grant-type': 'access_token',
  Authorization: `Bearer ${token}`,
  'Content-Type': 'application/json',
};

const basis = 'https://app1.edoobox.com/v2';
const ressourcen = [
  { name: 'edo_admins',          pfade: ['/admin/list', '/admins/list', '/administrator/list'] },
  { name: 'Vat',                 pfade: ['/vat/list', '/vats/list'] },
  { name: 'Countries',           pfade: ['/country/list', '/countries/list'] },
  { name: 'edo_categories',      pfade: ['/category/list', '/categories/list'] },
  { name: 'edo_offers',          pfade: ['/offer/list', '/offers/list'] },
  { name: 'edo_users',           pfade: ['/user/list', '/users/list'] },
  { name: 'edo_dates',           pfade: ['/date/list', '/dates/list', '/module/list', '/modules/list'] },
  { name: 'edo_bookings',        pfade: ['/booking/list', '/bookings/list'] },
  { name: 'edo_pricecategories', pfade: ['/pricecategory/list', '/pricecategories/list'] },
  { name: 'edo_attendances',     pfade: ['/attendance/list', '/attendances/list'] },
  { name: 'edo_invoices',        pfade: ['/invoice/list', '/invoices/list'] },
  { name: 'edo_transactions',    pfade: ['/transaction/list', '/transactions/list'] },
];

const relation = /(^|\.)(offer|offers|user|users|admin|admins|participant|participants|date|dates|booking|bookings|invoice|invoices|transaction|transactions|pay|paytrans|country|category|vat|number|permission)(\[\])?$/i;

function typ(v) {
  if (v === null) return 'null';
  if (Array.isArray(v)) return 'array';
  return typeof v;
}

function siehtWieIdAus(k) {
  return /^(booking|offer|user|admin|date|invoice|transaction|attendance|category|pricecategory)_[a-z0-9]+(?:_[a-z0-9-]+)?$/i.test(k)
    || /^[a-f0-9]{16,}$/i.test(k)
    || /^\d{7,}$/.test(k);
}

function datenAus(body) {
  const d = body?.data;
  if (Array.isArray(d)) return d;
  if (d && typeof d === 'object') return Object.values(d);
  return [];
}

function wertSignatur(v) {
  if (v === null || v === undefined || v === '') return null;
  if (typeof v === 'object') return null;
  return `${typeof v}:${String(v)}`;
}

function erfasse(stats, relationswerte, v, pfad) {
  if (!pfad) return;
  const s = stats.get(pfad) ?? { typen: new Set(), vorkommen: 0, gefuellt: 0 };
  s.typen.add(typ(v));
  s.vorkommen += 1;
  if (v !== null && v !== undefined && v !== '') s.gefuellt += 1;
  stats.set(pfad, s);

  if (relation.test(pfad)) {
    const sig = wertSignatur(v);
    if (sig !== null) {
      const r = relationswerte.get(pfad) ?? { gefuellt: 0, verschieden: new Set() };
      r.gefuellt += 1;
      r.verschieden.add(sig);
      relationswerte.set(pfad, r);
    }
  }

  if (Array.isArray(v)) {
    for (const x of v) erfasse(stats, relationswerte, x, pfad + '[]');
    return;
  }

  if (v && typeof v === 'object') {
    const keys = Object.keys(v);
    const idMap = keys.length > 0 && keys.filter(siehtWieIdAus).length / keys.length >= 0.8;
    if (idMap) {
      for (const x of Object.values(v)) erfasse(stats, relationswerte, x, pfad + '.*');
    } else {
      for (const [k, x] of Object.entries(v)) erfasse(stats, relationswerte, x, pfad + '.' + k);
    }
  }
}

async function abruf(pfad, start, reply) {
  try {
    return await this.helpers.httpRequest({
      method: 'GET',
      url: basis + pfad,
      headers,
      qs: { 'limit[start]': start, 'limit[reply]': reply },
      json: true,
      returnFullResponse: true,
      timeout: 60000,
      ignoreHttpStatusErrors: true,
    });
  } catch (e) {
    return {
      statusCode: e?.response?.status ?? e?.httpCode ?? 'Fehler',
      body: { _fehler: String(e?.message ?? e).slice(0, 160) },
    };
  }
}

const ausgabe = [];

for (const ressource of ressourcen) {
  const versuche = [];
  let treffer = null;

  for (const pfad of ressource.pfade) {
    const probe = await abruf.call(this, pfad, 0, 3);
    const status = probe.statusCode ?? 'Fehler';
    const zeilen = status >= 200 && status < 300 ? datenAus(probe.body).length : 0;
    versuche.push(`${pfad}=${status}/${zeilen}`);
    if (!treffer && status >= 200 && status < 300 && probe.body && Object.prototype.hasOwnProperty.call(probe.body, 'data')) {
      treffer = pfad;
    }
  }

  if (!treffer) {
    ausgabe.push({
      json: {
        schritt: 'S51',
        bereich: 'A Ressource',
        ressource: ressource.name,
        endpoint: '-',
        datensaetze: 0,
        feldpfade: 0,
        hinweis: 'Kein verwendbarer Endpunkt / ' + versuche.join(' ; '),
      },
    });
    continue;
  }

  const stats = new Map();
  const relationswerte = new Map();
  const reply = 2000;
  let start = 0;
  let gesamt = 0;
  let gemeldet = null;
  let seiten = 0;
  let abbruch = 'vollstaendig';
  let vorigeSignatur = null;

  while (seiten < 50) {
    const antwort = await abruf.call(this, treffer, start, reply);
    const status = antwort.statusCode ?? 'Fehler';
    if (!(status >= 200 && status < 300)) {
      abbruch = `Fehler ${status} ab Offset ${start}`;
      break;
    }

    const body = antwort.body ?? {};
    const rows = datenAus(body);
    if (gemeldet === null && body.limit?.total !== undefined) gemeldet = Number(body.limit.total);
    seiten += 1;

    const ids = rows.slice(0, 2).concat(rows.slice(-2)).map((r) => {
      if (!r || typeof r !== 'object') return typ(r);
      return r.id ?? r.number ?? Object.keys(r).sort().join(',');
    });
    const signatur = JSON.stringify(ids);
    if (seiten > 1 && signatur === vorigeSignatur && rows.length > 0) {
      abbruch = 'Pagination vom Endpunkt ignoriert; Wiederholung erkannt';
      break;
    }
    vorigeSignatur = signatur;

    for (const row of rows) {
      if (!row || typeof row !== 'object') continue;
      for (const [k, v] of Object.entries(row)) erfasse(stats, relationswerte, v, k);
    }

    gesamt += rows.length;
    start += rows.length;
    if (rows.length === 0) break;
    if (gemeldet !== null && start >= gemeldet) break;
    if (rows.length < reply) break;
  }

  if (seiten >= 50) abbruch = 'Sicherheitsgrenze von 50 Seiten erreicht';

  const feldbericht = [...stats.entries()]
    .sort(([a], [b]) => a.localeCompare(b))
    .map(([pfad, s]) => `${pfad}{${[...s.typen].sort().join('+')};${s.gefuellt}/${s.vorkommen}}`)
    .join(' | ');

  const relationsbericht = [...relationswerte.entries()]
    .sort(([a], [b]) => a.localeCompare(b))
    .map(([pfad, r]) => `${pfad}{gefüllt:${r.gefuellt};verschieden:${r.verschieden.size}}`)
    .join(' | ');

  ausgabe.push({
    json: {
      schritt: 'S51',
      bereich: 'A Ressource',
      ressource: ressource.name,
      endpoint: treffer,
      datensaetze: gesamt,
      feldpfade: stats.size,
      hinweis: `gemeldet ${gemeldet ?? '-'} / Seiten ${seiten} / ${abbruch} / Versuche ${versuche.join(' ; ')}`,
    },
  });
  ausgabe.push({
    json: {
      schritt: 'S51',
      bereich: 'B Feldinventar',
      ressource: ressource.name,
      endpoint: treffer,
      datensaetze: gesamt,
      feldpfade: stats.size,
      hinweis: feldbericht || '-',
    },
  });
  ausgabe.push({
    json: {
      schritt: 'S51',
      bereich: 'C Beziehungen',
      ressource: ressource.name,
      endpoint: treffer,
      datensaetze: gesamt,
      feldpfade: relationswerte.size,
      hinweis: relationsbericht || 'keine technischen Beziehungsfelder erkannt',
    },
  });
}

return ausgabe;
